using UnityEngine; namespace Crownfall.Skills { [CreateAssetMenu(fileName="HealEffect",menuName="Crownfall/Skills/Effects/Heal")] public sealed class HealEffectDefinition:SkillEffectDefinition { public float flatHeal=220; public float skillPowerScaling=1.8f; public override void Execute(SkillContext c,Crownfall.Units.Unit t){if(t!=null&&t.Team==c.Caster.Team)t.Heal(flatHeal+c.Caster.Definition.skillPower*skillPowerScaling);} } }
